const body = $('Webhook Site Report').first().json.body || {};
if (!body.project_id) {
  const err1 = { valid: false, error: 'project_id obligatorio' };
  return [{ json: err1 }];
}
let photoUrls = body.photo_urls;
if (!photoUrls && body.photo_url) photoUrls = [body.photo_url];
if (!Array.isArray(photoUrls) || photoUrls.length === 0) {
  const err2 = { valid: false, error: 'photo_url o photo_urls (array) obligatorio' };
  return [{ json: err2 }];
}
const urls = photoUrls.filter(u => typeof u === 'string' && u.startsWith('http'));
if (urls.length === 0) {
  const err3 = { valid: false, error: 'photo_urls deben ser http(s)' };
  return [{ json: err3 }];
}
const out = {
  valid: true,
  project_id: body.project_id,
  photo_urls: urls.slice(0, 6),
  observations: (body.observations || '').toString().slice(0, 2000),
  expected_phase: body.expected_phase || null,
  reporter: body.reporter || 'arquitecto'
};
return [{ json: out }];

const ctx = $input.first().json.context || {};
const input = $('Validate Input').first().json;
const plan = ctx.plan || {};
const phases = plan.phases || [];
const design = ctx.last_design || {};

const phasesText = Array.isArray(phases) && phases.length > 0
  ? phases.map((ph, i) => (i+1) + '. ' + (ph.name || ph.title || 'Fase ' + (i+1)) + ': ' + (ph.description || ph.scope || '?')).join('\n')
  : '(Plan no disponible)';

const systemPrompt = 'Eres un arquitecto técnico experto en seguimiento de obra. Analizas fotos de obra contra el plan y detectas estado, desviaciones e incidencias. Respondes SOLO con JSON válido sin markdown.';

const userText = [
  'Analiza estas fotos de obra del proyecto "' + (ctx.project_name || '?') + '" (tipo: ' + (ctx.project_type || '?') + ').',
  '',
  'PLAN DE OBRA APROBADO:',
  phasesText,
  '',
  'OPCION DE DISENO SELECCIONADA: ' + (design.title || 'No disponible'),
  design.description ? '  Descripcion: ' + design.description.substring(0, 500) : '',
  '',
  input.expected_phase ? 'FASE QUE DEBERIA ESTAR EN CURSO: ' + input.expected_phase : '',
  input.observations ? 'NOTAS DEL ARQUITECTO: ' + input.observations : '',
  '',
  'Devuelve JSON con esta estructura exacta:',
  '{',
  '  "detected_phase": "nombre fase detectada en la foto",',
  '  "progress_pct": 0-100,',
  '  "vision_summary": "2-3 frases describiendo lo visible",',
  '  "deviations": [{"type":"plan|design|quality", "description":"...", "severity":"low|medium|high"}],',
  '  "issues_detected": [{"category":"safety|quality|materials|workmanship|other", "description":"...", "action_recommended":"...", "severity":"low|medium|high"}],',
  '  "matches_plan": true|false,',
  '  "confidence": "low|medium|high"',
  '}',
  '',
  'No inventes elementos. Si no ves algo claramente, dilo. Si la foto no permite analisis fiable, devuelve confidence: "low".'
].filter(Boolean).join('\n');

const contentArr = [{ type: 'text', text: userText }];
for (const url of input.photo_urls) {
  contentArr.push({ type: 'image_url', image_url: { url: url, detail: 'high' } });
}

const payload = {
  model: 'gpt-4o',
  max_tokens: 1500,
  temperature: 0.2,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: contentArr }
  ]
};
return [{ json: { project_id: input.project_id, observations: input.observations, expected_phase: input.expected_phase, reporter: input.reporter, photo_urls: input.photo_urls, payload: payload, started_at: Date.now() } }];

const llm = $input.first().json;
const built = $('Build Vision Prompt').first().json;
const content = llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content || '';
const usage = llm.usage || {};
const tokensIn = usage.prompt_tokens || 0;
const tokensOut = usage.completion_tokens || 0;
const cost = (tokensIn / 1000) * 0.0025 + (tokensOut / 1000) * 0.01;
const durationMs = Date.now() - (built.started_at || Date.now());

let parsed = {};
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch (e) {
  parsed = { vision_summary: 'Error parsing LLM response: ' + e.message, confidence: 'low' };
}

const issues = Array.isArray(parsed.issues_detected) ? parsed.issues_detected : [];
const deviations = Array.isArray(parsed.deviations) ? parsed.deviations : [];
const hasHigh = issues.some(i => i && i.severity === 'high') || deviations.some(d => d && d.severity === 'high');
const flagged = hasHigh || issues.length >= 3;

const out = {
  project_id: built.project_id,
  photo_urls: built.photo_urls,
  observations: built.observations || null,
  expected_phase: built.expected_phase || null,
  reporter: built.reporter,
  detected_phase: parsed.detected_phase || null,
  progress_pct: typeof parsed.progress_pct === 'number' ? parsed.progress_pct : null,
  deviations: deviations,
  issues_detected: issues,
  vision_summary: parsed.vision_summary || '',
  vision_raw: parsed,
  llm_model: llm.model || 'gpt-4o',
  llm_tokens_in: tokensIn,
  llm_tokens_out: tokensOut,
  llm_cost: Math.round(cost * 100000) / 100000,
  status: flagged ? 'flagged' : 'analyzed',
  high_severity_count: issues.filter(i => i && i.severity === 'high').length + deviations.filter(d => d && d.severity === 'high').length,
  duration_ms: durationMs
};
return [{ json: out }];

