INSERT INTO site_reports (
  project_id, reporter, photo_urls, observations, expected_phase,
  detected_phase, progress_pct, deviations, issues_detected,
  vision_summary, vision_raw, llm_model, llm_tokens_in, llm_tokens_out, llm_cost, status
) VALUES (
  $1::uuid, $2, $3::text[], $4, $5,
  $6, NULLIF($7,'')::numeric, $8::jsonb, $9::jsonb,
  $10, $11::jsonb, $12, $13::int, $14::int, $15::numeric, $16
) RETURNING id, status, progress_pct;

