const sr = $('Parse Vision Response').first().json;
const saved = $('Insert Site Report').first().json;
const project = $('Load Project + Plan').first().json.context || {};
const issues = sr.issues_detected || [];
const devs = sr.deviations || [];
const issueRows = issues.map(i => '<li><b>[' + (i.severity || '?').toUpperCase() + ']</b> ' + (i.category || '?') + ': ' + (i.description || '?') + (i.action_recommended ? '<br><i>Recomendado: ' + i.action_recommended + '</i>' : '') + '</li>').join('');
const devRows = devs.map(d => '<li><b>[' + (d.severity || '?').toUpperCase() + ']</b> ' + (d.type || '?') + ': ' + (d.description || '?') + '</li>').join('');
const photoTags = (sr.photo_urls || []).map(u => '<a href="' + u + '">foto</a>').join(' &middot; ');
const html = '<h2>⚠ Alerta de obra — ' + (project.project_name || '?') + '</h2>' +
  '<p><b>Detectado:</b> ' + (sr.detected_phase || '?') + ' &middot; <b>Progreso estimado:</b> ' + (sr.progress_pct !== null ? sr.progress_pct + '%' : 'n/a') + '</p>' +
  '<p><b>Resumen visión:</b> ' + (sr.vision_summary || '?') + '</p>' +
  (issues.length ? '<h3>Incidencias detectadas (' + issues.length + ')</h3><ul>' + issueRows + '</ul>' : '') +
  (devs.length ? '<h3>Desviaciones plan/diseño (' + devs.length + ')</h3><ul>' + devRows + '</ul>' : '') +
  '<p><b>Fotos:</b> ' + photoTags + '</p>' +
  '<p style="font-size:12px;color:#666">Report ID: ' + saved.id + '</p>';
return [{ json: { html: html, project_name: project.project_name, report_id: saved.id, issue_count: issues.length, dev_count: devs.length } }];

const err = $input.first().json;
const built = $('Build Vision Prompt').first().json;
const msg = (err && (err.message || (err.error && err.error.message))) || 'unknown vision error';
return [{ json: { project_id: built.project_id, photo_urls: built.photo_urls, error: msg } }];
